hugin_null_if_sentinel:
select case
    when try_cast(
    nullif(
      replace(
        replace(trim(cast(sentinel as string)), ' ', ''),
        ',', '.'
      ),
      ''
    ) as double
  ) is not null
     and try_cast(
    nullif(
      replace(
        replace(trim(cast(num as string)), ' ', ''),
        ',', '.'
      ),
      ''
    ) as double
  ) = try_cast(
    nullif(
      replace(
        replace(trim(cast(sentinel as string)), ' ', ''),
        ',', '.'
      ),
      ''
    ) as double
  )
      then cast(null as double)when lower(trim(cast(num as string))) in ('nan', '-nan', 'null')
      then cast(null as double)
    else try_cast(
    nullif(
      replace(
        replace(trim(cast(num as string)), ' ', ''),
        ',', '.'
      ),
      ''
    ) as double
  )
  end as v from (
select '15/9-F-15 D' as uid, '41000' as serial, '1,5' as num, '-999.25' as sentinel union all
select '15/9-F-4'   as uid, '39600' as serial, ' 12 345,6 ' as num, '-999.25' as sentinel union all
select '15/9-F-11 T2' as uid, '43000' as serial, 'nan' as num, '-9999' as sentinel union all
select 'NO 15/9-F-1 C' as uid, '39630' as serial, '3.25' as num, '-999.2500' as sentinel
) t order by 1

hugin_safe_divide:
select case when coalesce(0.0, 0) = 0 then cast(null as double)
       else cast(1.0 as double) / cast(0.0 as double)
  end as v
